import random, time
from circuit import CircuitBreaker  # bulkhead + breaker abstraction

# Fixed policy: worst-case bounded, no adaptation at runtime.
TIMEOUT_S = 0.8        # per-attempt deadline: fail fast, don't queue
MAX_RETRIES = 2        # global budget for this request tree
BASE_BACKOFF_S = 0.05

breaker = CircuitBreaker(fail_threshold=20, reset_timeout_s=30)

def call_with_robustness(request, downstream):
    if breaker.is_open():
        return fallback(request)  # degraded, bounded, explicit
    attempt = 0
    while True:
        try:
            # deadline propagation: downstream must respect TIMEOUT_S
            return downstream.call(request, timeout=TIMEOUT_S)
        except TransientError:
            if attempt >= MAX_RETRIES:
                breaker.record_failure()
                return fallback(request)
            # jitter breaks retry synchrony; budget stops amplification
            sleep = BASE_BACKOFF_S * (2 ** attempt) + random.uniform(0, 0.05)
            time.sleep(sleep)
            attempt += 1
        except PermanentError:
            # do NOT retry: 4xx, validation, non-idempotent without key
            return fallback(request)
